$t['wrong seller not estimated']=!order_discount_estimate_allowed($discounted,[$a,$b,$d],'999',['P'=>true]);
foreach($t as $n=>$ok)echo ($ok?'PASS':'FAIL')." $n\n";exit(in_array(false,$t,true)?1:0);
